    var frontWall2 = new THREE.Mesh(frontWallGeom1, wallMat);
    frontWall2.position.set(halfW / 2 + SHAFT_WIDTH / 2, FLOOR_COUNT * FLOOR_HEIGHT / 2, BUILDING_DEPTH / 2);
    group.add(frontWall2);

    return group;
}

// === Elevator Car Creation ===
